import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"35、【晋】 坤下离上","description":"温公易说 - 35、【晋】 坤下离上","frontmatter":{"title":"35、【晋】 坤下离上","description":"温公易说 - 35、【晋】 坤下离上"},"headers":[],"relativePath":"zh/classics/wengong/036.md","filePath":"zh/classics/wengong/036.md"}'),n={name:"zh/classics/wengong/036.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_35、【晋】-坤下离上" tabindex="-1">35、【晋】 坤下离上 <a class="header-anchor" href="#_35、【晋】-坤下离上" aria-label="Permalink to “35、【晋】 坤下离上”">​</a></h1><h3 id="彖曰-晋-进也。明出地上-顺而丽乎大明。柔进而上行-是以康侯用锡马蕃庶-昼日三接也。" tabindex="-1">彖曰：晋，进也。明出地上，顺而丽乎大明。柔进而上行，是以康侯用锡马蕃庶，昼日三接也。 <a class="header-anchor" href="#彖曰-晋-进也。明出地上-顺而丽乎大明。柔进而上行-是以康侯用锡马蕃庶-昼日三接也。" aria-label="Permalink to “彖曰：晋，进也。明出地上，顺而丽乎大明。柔进而上行，是以康侯用锡马蕃庶，昼日三接也。”">​</a></h3><h3 id="象曰-明出地上-晋。君子以自昭明德。" tabindex="-1">象曰：明出地上，晋。君子以自昭明德。 <a class="header-anchor" href="#象曰-明出地上-晋。君子以自昭明德。" aria-label="Permalink to “象曰：明出地上，晋。君子以自昭明德。”">​</a></h3><p>君子进其明德，如日之升也。</p><h3 id="初六-晋如摧如-贞吉。罔孚裕无咎-象曰-晋如摧如-独行正也。裕无咎-未受命也。" tabindex="-1">初六：晋如摧如，贞吉。罔孚裕无咎 象曰：晋如摧如，独行正也。裕无咎，未受命也。 <a class="header-anchor" href="#初六-晋如摧如-贞吉。罔孚裕无咎-象曰-晋如摧如-独行正也。裕无咎-未受命也。" aria-label="Permalink to “初六：晋如摧如，贞吉。罔孚裕无咎 象曰：晋如摧如，独行正也。裕无咎，未受命也。”">​</a></h3><p>初进者德业未着，人莫之信。躁以求之则凶，宽以待之无咎。未受命者，受上命然后可进，无命而进凶道也。</p><h3 id="六二-晋如愁如-贞吉。受兹介福于其王母-象曰-受兹介福-以中正也。" tabindex="-1">六二：晋如愁如，贞吉。受兹介福于其王母 象曰：受兹介福，以中正也。 <a class="header-anchor" href="#六二-晋如愁如-贞吉。受兹介福于其王母-象曰-受兹介福-以中正也。" aria-label="Permalink to “六二：晋如愁如，贞吉。受兹介福于其王母 象曰：受兹介福，以中正也。”">​</a></h3><h3 id="六三-众允悔亡-象曰-众允之志-上行也。" tabindex="-1">六三：众允悔亡 象曰：众允之志，上行也。 <a class="header-anchor" href="#六三-众允悔亡-象曰-众允之志-上行也。" aria-label="Permalink to “六三：众允悔亡 象曰：众允之志，上行也。”">​</a></h3><h3 id="九四-晋如鼫鼠-贞厉-象曰-鼫鼠贞厉-位不当也。" tabindex="-1">九四：晋如鼫鼠，贞厉 象曰：鼫鼠贞厉，位不当也。 <a class="header-anchor" href="#九四-晋如鼫鼠-贞厉-象曰-鼫鼠贞厉-位不当也。" aria-label="Permalink to “九四：晋如鼫鼠，贞厉 象曰：鼫鼠贞厉，位不当也。”">​</a></h3><h3 id="六五-悔亡-失得勿恤-往吉无不利-象曰-失得勿恤-往有庆也。" tabindex="-1">六五：悔亡，失得勿恤，往吉无不利 象曰：失得勿恤，往有庆也。 <a class="header-anchor" href="#六五-悔亡-失得勿恤-往吉无不利-象曰-失得勿恤-往有庆也。" aria-label="Permalink to “六五：悔亡，失得勿恤，往吉无不利 象曰：失得勿恤，往有庆也。”">​</a></h3><h3 id="上九-晋其角-维用伐邑-厉吉无咎-贞吝-象曰-维用伐邑-道未光也。" tabindex="-1">上九：晋其角，维用伐邑，厉吉无咎，贞吝 象曰：维用伐邑，道未光也。 <a class="header-anchor" href="#上九-晋其角-维用伐邑-厉吉无咎-贞吝-象曰-维用伐邑-道未光也。" aria-label="Permalink to “上九：晋其角，维用伐邑，厉吉无咎，贞吝 象曰：维用伐邑，道未光也。”">​</a></h3>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
